arguments:
"C:\\WINDOWS\\System32\\WindowsPowerShell\\v1.0\\powershell.exe" -Command '$paths = @('"'plans\\hello-cli\\00-ambiguity-register.md','plans\\hello-cli\\00-index.md','plans\\hello-cli\\01-requirements.md','plans\\hello-cli\\02-current-state.md','plans\\hello-cli\\03-01-command-and-tests.md','plans\\hello-cli\\07-testing-strategy.md','plans\\hello-cli\\99-execution-plan.md')
"'$sha = [System.Security.Cryptography.SHA256]::Create()
try {
  foreach ($path in $paths) {
    $text = [System.IO.File]::ReadAllText((Resolve-Path -LiteralPath $path))
    if ($text.Length -gt 0 -and $text[0] -eq [char]0xFEFF) { $text = $text.Substring(1) }
    $text = $text -replace "`r`n", "`n" -replace "`r", "`n"
    $lines = $text -split "`n", -1 | ForEach-Object { $_.TrimEnd('"' ', \""'`t") }
    $normalized = ($lines -join "`n").TrimEnd("`n") + "`n"
    $hash = $sha.ComputeHash([System.Text.Encoding]::UTF8.GetBytes($normalized))
    $digest = ([System.BitConverter]::ToString($hash)).Replace('"'-', '').ToLowerInvariant()
    \""'$path`tsha256:$digest"
  }
} finally { $sha.Dispose() }'

